update pages set contenu = '{"sections":[]}'::jsonb where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance améliorative","mecanisme":"Nous cherchons la cause de la panne qui revient, puis nous modifions l''équipement pour qu''elle ne revienne plus. Capteur déplacé, organe redimensionné, accès repris, logique automate corrigée. L''écart se mesure avant et après, sur vos propres indicateurs.","cta":"Demander un diagnostic maintenance","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"+ 80","libelle":"clients réguliers, sur plus de 120 clients au total"},{"valeur":"8 domaines","libelle":"mécanique, électricité, électromécanique, automatisme, hydraulique, pneumatique, soudure et chaudronnerie, robotique"}]},{"type":"probleme","punchline":"La même panne revient tous les deux mois. Vous la réparez, elle revient. La réparer une quatrième fois n''est pas une stratégie.","puces":[{"accroche":"Vous payez deux fois la même réparation.","texte":"Main d''œuvre, pièce, casse collatérale, rebuts. Le coût annuel de la défaillance dépasse souvent celui de la modification qui la supprime."},{"accroche":"Le problème n''est plus la panne, c''est la conception.","texte":"Capteur mal placé, roulement sous-dimensionné, armoire qui chauffe. Réparer à l''identique remet la cause en service avec la pièce neuve."},{"accroche":"Vos opérateurs ont inventé une astuce pour contourner le défaut.","texte":"Une astuce qui dure est toujours le symptôme d''une amélioration jamais faite."},{"accroche":"Personne n''a le temps de sortir du quotidien.","texte":"L''équipe absorbe le correctif, les postes de nuit et les aléas. Le chantier de fond attend."}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"offre","lignes":[{"prestation":{"accroche":"Supprimer la panne qui revient","texte":"extraction de l''historique GMAO, cinq pourquoi et arbre des causes, analyse des modes de défaillance sur les actifs sensibles, modification chiffrée, contrôle du résultat."},"benefice":"L''équipement sort du top 3 des heures de dépannage, et il n''y revient pas."},{"prestation":{"accroche":"Gagner du temps de réparation","texte":"accès facilités, point de graissage déporté, repérage des câbles, standardisation des composants, documentation refaite."},"benefice":"Votre MTTR baisse sans changer la machine. Chaque intervention future coûte moins d''immobilisation."},{"prestation":{"accroche":"Fiabiliser la partie commande","texte":"reprise de la logique automate, temporisations revues, diagnostics lisibles sur pupitre, alarmes explicites au lieu d''un code défaut muet."},"benefice":"Le technicien de garde sait quoi faire à 3h du matin sans appeler personne."},{"prestation":{"accroche":"Traiter les causes mécaniques de fond","texte":"redimensionnement d''un organe qui lâche, massif renforcé, accouplement adapté, guidage ajusté, traitement thermique de l''armoire électrique."},"benefice":"La cascade s''arrête. Un balourd ne détruit plus les paliers les uns après les autres."},{"prestation":{"accroche":"Instrumenter un équipement critique","texte":"capteurs de vibration ou de température, remontée vers votre supervision, seuils d''alerte réglés avec vos équipes."},"benefice":"Deux ou trois actifs suffisent pour savoir où porter l''effort suivant, sans instrumenter tout le parc."},{"prestation":{"accroche":"Mettre en sécurité une machine ancienne","texte":"protecteurs, arrêts d''urgence, verrouillages, suppression des gestes à risque."},"benefice":"Le geste dangereux disparaît du mode opératoire, il n''est plus seulement signalé."},{"prestation":{"accroche":"Moderniser sans remplacer","texte":"quand la mécanique est saine mais l''électronique dépassée, automate sans pièce de rechange, variateur plus fabriqué."},"benefice":"Le cycle de vie repart pour plusieurs années, au chiffrage d''une reprise et non d''un investissement neuf."}],"prose":[{"texte":"Matériel obsolète, pièces introuvables, notice perdue : la réponse tenable devient le [retrofit machine industrielle](/offres/retrofit/), et la [mise en conformité machine](/offres/retrofit/mise-en-conformite-machine/) quand la sécurité est en jeu. Pour industrialiser la démarche sur tout un parc, l''abonnement [Zéro arrêt](/offres/zero-arret/) couvre les programmes suivis, l''analyse des causes et les améliorations mesurées."}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"deroule","etapes":[{"titre":"Vous décrivez la panne qui revient","texte":"équipement, fréquence, ce qui a déjà été changé, ce que dit la GMAO. Quelques minutes au téléphone évitent un déplacement pour rien."},{"titre":"Un technicien vous rappelle dans l''heure.","texte":"Vous savez rapidement si nous avons la compétence, et laquelle."},{"titre":"Nous posons le diagnostic maintenance, gratuitement","texte":"parc, criticité, historique sur douze mois, contraintes d''exploitation, palmarès des équipements par heures immobilisées."},{"titre":"Nous cadrons et nous chiffrons","texte":"périmètre, cause racine identifiée, gain attendu, arrêt nécessaire, devis. Vous comparez le montant au coût annuel de la défaillance."},{"titre":"Nous réalisons pendant un arrêt planifié","texte":"consignation, modification, essais, remise en service. Une reprise improvisée en pleine urgence est une dette technique de plus."},{"titre":"Nous prouvons et nous documentons","texte":"écart mesuré avant et après sur les indicateurs convenus, schémas mis à jour, gammes reprises, dossier machine complété, équipes formées."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Chaque modification est tracée et laissée entre vos mains.","texte":"Schéma à jour, dossier machine complété, gammes reprises. Une machine améliorée dont le plan n''est pas mis à jour devient impossible à dépanner pour le suivant, y compris pour nous."},{"accroche":"Des interventions cadrées par la démarche MASE et l''évaluation EcoVadis.","texte":"Les attestations sont transmises avec chaque plan de prévention, avant la première journée sur site."}]},{"type":"cta","question":"Besoin de supprimer la panne qui revient au lieu de la réparer une fois de plus ?","bouton":"Demander un diagnostic maintenance","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Diagnostic de défaillances récurrentes sur un parc machines, fabrication de joints techniques","texte":"étude technique machine par machine, plusieurs options chiffrées, remise en état du parc existant plutôt que rachat de matériel neuf, depuis février 2024","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Réduction des incidents machine récurrents, pièces mécaniques de précision","texte":"un technicien à temps plein sur centres d''usinage grande vitesse, presses et commandes numériques, plan de maintenance repris en continu, 2025","lienLibelle":"Étude de cas VOIT : site du Grand Est","lienHref":"/preuves/voit-grand-est/"},{"titre":"Sortie du mode pompier sur un parc hétérogène, papier et emballage","texte":"un technicien polyvalent intégré aux lignes, temps d''arrêt réduits et préventif qui n''est plus sacrifié aux urgences, 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"},{"titre":"Travaux de remise en état d''installations critiques, traitement des eaux industrielles","texte":"électromécanicien polyvalent habilité risque chimique niveau 1 avant l''entrée sur site, mission de 6 mois depuis février 2026","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Temps de remise en service raccourci sur des lignes à haute cadence, nutrition infantile","texte":"deux techniciens intégrés en 3x8 sur les lignes liquides et le conditionnement poudre, site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"}]},{"type":"objections","questions":[{"question":"Combien coûte une action améliorative ?","reponse":"Pas de prix catalogue : la modification se chiffre sur devis, une fois le diagnostic posé. Le bon repère n''est pas le montant du chantier, mais son écart avec le coût annuel de la défaillance qu''il supprime."},{"question":"Faut-il un contrat pour lancer une amélioration ?","reponse":"Non. Une action isolée se traite en intervention ponctuelle, sur devis. L''abonnement [Zéro arrêt](/offres/zero-arret/) se discute quand le même équipement revient plusieurs fois dans l''année et que le budget n''est plus pilotable."},{"question":"Pouvez-vous reprendre un parc déjà suivi par un autre prestataire ?","reponse":"Oui. Nous partons de l''existant : historique GMAO, plans, gammes en place. Le diagnostic maintenance est gratuit et ses conclusions vous restent acquises, y compris si vous décidez de poursuivre avec votre prestataire actuel."},{"question":"Qui répond de la sécurité pendant les travaux ?","reponse":"Nos interventions sont cadrées par la démarche MASE et l''évaluation EcoVadis, attestations transmises avec chaque plan de prévention. La modification se réalise pendant un arrêt planifié, machine consignée, essais avant remise en service."},{"question":"Qui réalise ces travaux, nos équipes ou un prestataire ?","reponse":"Les deux fonctionnent, et beaucoup de sites gardent les améliorations légères en interne. Nos techniciens sont salariés de Migen, retenus après entretien technique et comportemental, 10 % des candidats évalués. Nous documentons chaque action pour que vos équipes la reproduisent sans nous."},{"question":"Intervenez-vous partout en France ?","reponse":"Oui. Nos quatre agences sont à Lyon (siège), Montréal, Dubaï et Madrid, et nos équipes se déplacent partout en France. Dites-nous où se trouve l''équipement et dans quel domaine technique, nous vous disons qui intervient."}]}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"ctaFinal","question":"Besoin de savoir quel équipement de votre parc vous coûte le plus cher chaque année ?","bouton":"Demander un diagnostic maintenance","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]'::jsonb) where path = '/expertises/types-de-maintenance/maintenance-ameliorative/';
